export function Search({ navigation }: ScreenProps<'Search'>) {
  const [q, setQ] = useState('');
  const [results, setResults] = useState<Product[]>([]);
  useEffect(() => {
    if (!q) {
      setResults([]);
      return;
    }
    searchProducts(q).then(r => setResults(r.body));
  }, [q]);
